from fractions import Fraction

n = int(input())
for i in range(n):
    b = int(input())
    p = int(input())
    q = int(input())
    x = Fraction(p, q)
    if x <= 0:
        print(f"log_{b} of {x}: undefined")
    else:
        y = 0
        power = Fraction(1)
        while power * b <= x:
            power = power * b
            y = y + 1
        while power > x:
            power = power / b
            y = y - 1
        if power == x:
            print(f"log_{b} of {x}: exactly {y}")
        else:
            print(f"log_{b} of {x}: between {y} and {y + 1}")

from fractions import Fraction

n = int(input())
for i in range(n):
    a = int(input())
    c = int(input())
    if a == 0:
        if c > 0:
            print("domain: all real numbers")
        else:
            print("domain: empty")
    else:
        edge = Fraction(-c, a)
        print(f"asymptote: x = {edge}")
        if a > 0:
            print(f"domain: x > {edge}")
        else:
            print(f"domain: x < {edge}")
